package com.collaborativecanvas.server.integration;
import com.collaborativecanvas.server.ServerApplication;import com.collaborativecanvas.server.repository.*;import com.collaborativecanvas.server.service.RoomService;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.test.context.DynamicPropertyRegistry;import org.springframework.test.context.DynamicPropertySource;import org.testcontainers.junit.jupiter.*;import org.testcontainers.containers.PostgreSQLContainer;import static org.junit.jupiter.api.Assertions.*;
/** Runs Flyway and actual JSONB persistence against PostgreSQL; skipped only when Docker is unavailable. */
@Testcontainers(disabledWithoutDocker = true) @SpringBootTest(classes=ServerApplication.class)
class PostgresPersistenceIT { @Container static final PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine"); @DynamicPropertySource static void postgres(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);} @Autowired RoomService rooms; @Autowired RoomRepository roomRepository; @Autowired CanvasSnapshotRepository snapshots; @Autowired ObjectMapper mapper;
 @Test void flywayCreatesAndPersistsInitialSnapshot(){var created=rooms.create("Integration");var room=roomRepository.findByRoomCode(created.roomId()).orElseThrow();var snapshot=snapshots.latestAtOrBefore(room.id,0,org.springframework.data.domain.PageRequest.of(0,1)).getFirst();assertEquals(0,snapshot.snapshotSequenceNumber);assertEquals(1,snapshot.snapshotJson.path("schemaVersion").asInt());}
}
